const j = $('Decide cancel (w10.applyCancel)').item.json;
const notice = L.brokerNotice(j.d.broker_notice, j.ld);
const who = (String(j.ld.first_name || '').trim() + ' ' + (j.ld.last_name ? String(j.ld.last_name).trim().slice(0, 1) + '.' : '')).trim();
const dayOf = (iso) => new Date(Date.parse(iso) + 7200000).toISOString().slice(0, 10);
// Outside the broker's 24-h window: approved utility template broker_booking_changed (I-35a); the howzit@ email still goes as the written record.
const tpl = (oldIso, nowText, dayIso) => ({ messaging_product: 'whatsapp', to: j.br.whatsapp_number, type: 'template', template: { name: 'broker_booking_changed', language: { code: 'en' }, components: [{ type: 'body', parameters: [String(j.br.contact_person || '').split(' ')[0] || 'there', who, L.METHOD_LABEL[j.bk.method] || String(j.bk.method || 'call'), L.slotLabel(oldIso), nowText].map((t) => ({ type: 'text', text: String(t) })) }, { type: 'button', sub_type: 'url', index: '0', parameters: [{ type: 'text', text: 'calendar?day=' + dayOf(dayIso) }] }] } });
const brokerWindow = Number.isFinite(j.br.last_inbound_ms) && Date.now() - j.br.last_inbound_ms < 86400000;
return { json: { ...j, op: 'rebook_after_cancel', to: 'broker', channel: brokerWindow ? 'whatsapp' : 'email', wa: brokerWindow ? { messaging_product: 'whatsapp', to: j.br.whatsapp_number, type: 'text', text: { body: notice } } : (j.br.whatsapp_number ? tpl(j.bk.appointment_date, 'Cancelled', j.bk.appointment_date) : null), email: { to: j.br.email, subject: 'SortMyCover booking cancelled', body: notice } } };

const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w10.mjs').href);
// I-39a: one message. delegate.body (W07's fixed lines + CANCEL_CONFIRM_Q) when present, else lines.mjs in the lead's language.
const j = $json; const m = L.cancelConfirmMessage(j.bk, j.ld, j.br, j.delegate || null);
return { json: { to: 'lead', ld: j.ld, wa: L.toWa(j.ld.phone, m) } };

const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w10.mjs').href);
const j = $json;
const p = String((j.msg && (j.msg.payload || j.msg.list_id)) || '').split(':');
const method = (j.delegate && j.delegate.method) || (p[0] === 'change_method' ? p[1] : null);
const d = L.changeMethod(j.bk, j.ld, j.br, method); return { json: { ...j, method, d } };

const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w10.mjs').href);
// Schedule C1A point 2 (default pending NH-42): a plain "I don't want a call" / "No thanks" stops messaging AT ONCE.
// The W13 claim (option b: nofit_criteria / no_call) is made by the hourly C1A sweep below from the message log.
const j = $json; const nc = L.applyNoCall(j.bk, j.ld);
return { json: { ...j, nc, op: 'cancel_all', booking_id: j.bk.id } };

const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w10.mjs').href);
const r = $json;
const d = L.c1aDecision({ lead: { id: r.lead_id, verified_at: r.verified_at, first_message_at: r.first_message_at, opted_out_at: r.opted_out_at, conv_state: r.conv_state || {} },
  booking: { id: r.booking_id, brand_id: r.brand_id, broker_id: r.broker_id, cycle_id: r.cycle_id, status: r.status, cancelled_at: r.cancelled_at },
  cancelled_by: r.cancelled_by === 'broker' ? 'broker' : 'lead', rebooked: r.rebooked, rebook_offered: r.rebook_offered,
  inbound_after_cancel: r.inbound_after_cancel || [], already_claimed: r.already_claimed, now_ms: Date.now(), mode: $env.W10_C1A_MODE || L.C1A_DEFAULT_MODE });
return { json: { ...r, d } };

const url = require('url');
const REPO = $env.REPO_DIR || '/home/node/repo';
const L = await import(url.pathToFileURL(REPO + '/automation/lib/w10.mjs').href);
// I-39a: change -> METHOD_CHANGED (or delegate.body); reject -> lead_lines + SAME_METHOD with the adviser's methods.
const j = $('Decide method change').item.json;
const m = L.methodMessage(j.d, j.bk, j.ld, j.br, j.delegate || null, j.method);
return { json: { to: 'lead', ld: j.ld, wa: L.toWa(j.ld.phone, m) } };
